function p2_check(bool $ok,string $label):void{global $checks;if(!$ok)throw new RuntimeException('FAIL: '.$label);$checks++;echo 'PASS: '.$label.PHP_EOL;}
function p2_client():CurlHandle{$c=curl_init();curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_COOKIEFILE=>'',CURLOPT_TIMEOUT=>15]);return $c;}
function p2_request(CurlHandle $c,string $path,?array $data=null):array{global $base;curl_setopt($c,CURLOPT_URL,$base.$path);if($data===null)curl_setopt($c,CURLOPT_HTTPGET,true);else{curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,http_build_query($data));}$raw=curl_exec($c);if($raw===false)throw new RuntimeException(curl_error($c));$size=curl_getinfo($c,CURLINFO_HEADER_SIZE);return['status'=>curl_getinfo($c,CURLINFO_RESPONSE_CODE),'headers'=>substr($raw,0,$size),'body'=>substr($raw,$size)];}
function p2_token(array $response):string{preg_match('/name="csrf_token" value="([a-f0-9]{64})"/',$response['body'],$m);if(!isset($m[1]))throw new RuntimeException('Missing CSRF token.');return$m[1];}
function p2_login(CurlHandle $c,string $email,string $password):void{$form=p2_request($c,'/public/login.php');$reply=p2_request($c,'/public/login.php',['csrf_token'=>p2_token($form),'email'=>$email,'password'=>$password]);p2_check($reply['status']===303,'Authenticated administrator login for Phase 2 tests');}
function p2_expect_validation(callable $call,string $message,string $label):void{try{$call();p2_check(false,$label);}catch(Phase2ValidationException $e){p2_check(in_array($message,$e->errors,true),$label);}}
