 phase2_set_establishment_active($est1,false,$userIds['administrator']);p2_check(!(bool)$pdo->query('SELECT is_active FROM establishments WHERE id='.$est1)->fetchColumn(),'Establishment deactivation works');phase2_set_establishment_active($est1,true,$userIds['administrator']);
 $estIds[]=$est2=phase2_create_establishment(['registration_code'=>$prefix.'-E2','business_name'=>'Second fictional business','owner_name'=>'Second Owner','address'=>'Second fictional address','registration_date'=>'2026-09-27'],$userIds['administrator']);
