 $trapIds[]=$trap1=phase2_create_trap($trapInput,$userIds['administrator']);p2_check((int)$pdo->query('SELECT establishment_id FROM grease_traps WHERE id='.$trap1)->fetchColumn()===$est1,'Grease trap creation works');
 $invalid=$trapInput;$invalid['low_threshold']='70';$invalid['medium_threshold']='50';p2_expect_validation(fn()=>phase2_create_trap($invalid,$userIds['administrator']),'Thresholds must follow low < medium < high < critical, between 0 and 100.','Invalid threshold order is rejected');
 $trapInput['establishment_id']=$est2;$trapInput['trap_code']=$prefix.'-T2';$trapInput['name']='Second test trap';$trapIds[]=$trap2=phase2_create_trap($trapInput,$userIds['administrator']);
 $deviceInput=['device_code'=>$prefix.'-D1','name'=>'Phase 2 ESP32','device_type'=>'ESP32 DevKit','firmware_version'=>'test','installation_date'=>'2026-09-27','establishment_id'=>$est1,'grease_trap_id'=>$trap1];
 $deviceIds[]=$device1=phase2_create_device($deviceInput,$userIds['administrator']);p2_check((int)$pdo->query('SELECT grease_trap_id FROM device_assignments WHERE device_id='.$device1.' AND ended_at IS NULL')->fetchColumn()===$trap1,'Device registration and assignment work');
 $cross=$deviceInput;$cross['establishment_id']=$est1;$cross['grease_trap_id']=$trap2;p2_expect_validation(fn()=>phase2_update_device($device1,$cross,$userIds['administrator']),'The selected grease trap does not belong to the selected establishment.','Cross-establishment assignment is rejected');
 $deviceInput['establishment_id']=$est2;$deviceInput['grease_trap_id']=$trap2;$deviceInput['name']='Updated Phase 2 ESP32';phase2_update_device($device1,$deviceInput,$userIds['administrator']);p2_check((int)$pdo->query('SELECT grease_trap_id FROM device_assignments WHERE device_id='.$device1.' AND ended_at IS NULL')->fetchColumn()===$trap2,'Device edit changes assignment and preserves history');
 $movedTrap=$trapInput;$movedTrap['establishment_id']=$est1;p2_expect_validation(fn()=>phase2_update_trap($trap2,$movedTrap,$userIds['administrator']),'A grease trap with device assignment history cannot be moved to another establishment.','Trap assignment history cannot be moved across establishments');
