 $admin=p2_client();p2_login($admin,$emails[0],$password);$dashboard=p2_request($admin,'/admin/dashboard.php');p2_check($dashboard['status']===200&&str_contains($dashboard['body'],'Administrative dashboard'),'Authenticated dashboard loads');
 $moduleResponses=[p2_request($admin,'/admin/grease-traps.php'),p2_request($admin,'/admin/grease-trap-view.php?id='.$trap2),p2_request($admin,'/admin/devices.php'),p2_request($admin,'/admin/device-view.php?id='.$device1)];p2_check(count(array_filter($moduleResponses,fn($response)=>$response['status']===200))===4,'Authenticated grease-trap and device pages load');
 $detail=p2_request($admin,'/admin/establishment-view.php?id='.$est1);p2_check(str_contains($detail['body'],'&lt;script&gt;alert(1)&lt;/script&gt;')&&!str_contains($detail['body'],'<script>alert(1)</script>'),'Stored HTML is escaped in Phase 2 details');
 $list=p2_request($admin,'/admin/establishments.php');$before=(int)$pdo->query("SELECT COUNT(*) FROM establishments WHERE registration_code='FORGED-P2'")->fetchColumn();$forged=p2_request($admin,'/admin/establishments.php',['csrf_token'=>'forged','action'=>'create','registration_code'=>'FORGED-P2','business_name'=>'Forged','owner_name'=>'Forged','address'=>'Forged','registration_date'=>'2026-09-27']);$after=(int)$pdo->query("SELECT COUNT(*) FROM establishments WHERE registration_code='FORGED-P2'")->fetchColumn();p2_check($forged['status']===403&&$before===$after,'Phase 2 CSRF validation blocks writes');
