 $auditCount=(int)$pdo->query("SELECT COUNT(*) FROM audit_logs WHERE user_id=".$userIds['administrator']." AND action IN ('ESTABLISHMENT_CREATED','ESTABLISHMENT_UPDATED','ESTABLISHMENT_DEACTIVATED','GREASE_TRAP_CREATED','DEVICE_REGISTERED','DEVICE_UPDATED','DEVICE_ASSIGNMENT_CHANGED')")->fetchColumn();p2_check($auditCount>=7,'Important Phase 2 changes are audited');
 echo PHP_EOL.$checks." Phase 2 checks passed.\n";
}finally{
 foreach($deviceIds as $id){$pdo->prepare('DELETE FROM device_assignments WHERE device_id=?')->execute([$id]);$pdo->prepare('DELETE FROM devices WHERE id=?')->execute([$id]);}
